import { Effect, Schema as S } from "effect"

export class InsufficientStock extends S.TaggedError<
  InsufficientStock,
  { readonly InsufficientStock: unique symbol }
>()("InsufficientStock", {
  sku: S.String,
  requested: S.Number,
  available: S.Number
}) {}

export interface Reservation {
  readonly sku: string
  readonly quantity: number
}

export const reserveStock = (
  sku: string,
  requested: number,
  available: number
): Effect.Effect<Reservation, InsufficientStock> => {
  if (requested > available) {
    return Effect.fail(
      new InsufficientStock({ sku, requested, available })
    )
  }

  return Effect.succeed({ sku, quantity: requested })
}

